-- Real SQL and triggers under simulated Auth claims, synthetic rolled-back data.
begin;
select extensions.no_plan();
create temporary table team_editor_fixture(owner_id uuid,reception_id uuid,business_id uuid,foreign_business uuid,empty_professional uuid,clinical_professional uuid,follow_up_professional uuid,foreign_professional uuid,patient_id uuid,service_id uuid,failed_service uuid,event_id uuid);
grant select on team_editor_fixture to authenticated;
do $fixture$
declare o uuid:=gen_random_uuid(); r uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); f uuid:=gen_random_uuid(); e uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); x uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); s uuid:=gen_random_uuid(); z uuid:=gen_random_uuid(); ev uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(o,o||'@example.test'),(r,r||'@example.test');
 insert into public.businesses(id,name,slug,industry) values(b,'Synthetic team commands',b::text,'other'),(f,'Synthetic foreign team',f::text,'other');
 update public.business_subscriptions set commercial_access_enabled=true,is_permanent=true,subscription_status='active',paid_until=null,grace_until=null,restricted_until=null,archived_at=null where business_id in(b,f);
 insert into public.business_users(business_id,user_id,role,status,accepted_at) values(b,o,'owner','active',now()),(b,r,'reception','active',now());
 insert into public.professionals(id,business_id,name) values(e,b,'Synthetic empty'),(c,b,'Synthetic clinical author'),(u,b,'Synthetic follow-up'),(x,f,'Synthetic foreign');
 insert into public.patients(id,business_id,owner_id,full_name) values(p,b,o,'Synthetic team patient');
 insert into public.clinical_entries(business_id,patient_id,owner_id,created_by_user_id,created_by_professional_id,entry_type,description) values(b,p,o,o,c,'Consulta','Synthetic history');
 insert into public.follow_ups(business_id,patient_id,assigned_professional_id,remind_on) values(b,p,u,current_date+1);
 insert into public.patient_profile_change_events(id,business_id,patient_id,changed_by_professional_id,changed_by_name,summary) values(ev,b,p,e,'Synthetic empty','Synthetic event');
 insert into team_editor_fixture values(o,r,b,f,e,c,u,x,p,s,z,ev);
end $fixture$;
select extensions.ok(not has_function_privilege('anon','public.create_professional_service_safely(uuid,uuid,uuid,text,integer,text)','execute'),'anonymous cannot create services');
select extensions.ok(not has_function_privilege('anon','public.delete_professional_safely(uuid,uuid)','execute'),'anonymous cannot delete professionals');
select extensions.ok(not has_function_privilege('authenticated','private.lock_team_manager_authority(uuid)','execute'),'private authority helper cannot be called directly');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select reception_id::text from team_editor_fixture),true);
select extensions.throws_ok($test$select public.create_professional_service_safely(business_id,empty_professional,service_id,'Synthetic service',30,null) from team_editor_fixture$test$,'P0001','TEAM_ACCESS_DENIED','reception cannot create a service directly');
select extensions.throws_ok($test$select public.get_professional_dependency_counts(business_id,empty_professional) from team_editor_fixture$test$,'P0001','TEAM_ACCESS_DENIED','reception cannot query private dependency counts');
select extensions.throws_ok($test$select public.delete_professional_safely(business_id,empty_professional) from team_editor_fixture$test$,'P0001','TEAM_ACCESS_DENIED','reception cannot bypass delete UI');
select set_config('request.jwt.claim.sub',(select owner_id::text from team_editor_fixture),true);
select extensions.throws_ok($test$select public.create_professional_service_safely(business_id,foreign_professional,service_id,'Synthetic service',30,null) from team_editor_fixture$test$,'P0001','TEAM_PROFESSIONAL_NOT_FOUND','foreign target is rejected before creation');
select extensions.is((select count(*) from public.services where id=(select service_id from team_editor_fixture)),0::bigint,'foreign assignment leaves no orphan service');
select extensions.throws_ok($test$select public.create_professional_service_safely(business_id,empty_professional,service_id,' ',30,null) from team_editor_fixture$test$,'P0001','TEAM_SERVICE_INVALID','blank service is rejected');
select extensions.lives_ok($test$select public.create_professional_service_safely(business_id,empty_professional,service_id,'Synthetic service',30,'20000') from team_editor_fixture$test$,'owner creates and assigns atomically');
select extensions.is((select count(*) from public.professional_services where service_id=(select service_id from team_editor_fixture) and professional_id=(select empty_professional from team_editor_fixture)),1::bigint,'assignment is persisted');
select extensions.lives_ok($test$select public.create_professional_service_safely(business_id,empty_professional,service_id,'Synthetic service',30,'20000') from team_editor_fixture$test$,'same operation identifier replays safely');
select extensions.is((select count(*) from public.services where id=(select service_id from team_editor_fixture)),1::bigint,'replay does not create another service');
select extensions.throws_ok($test$select public.create_professional_service_safely(business_id,empty_professional,service_id,'Different payload',30,'20000') from team_editor_fixture$test$,'P0001','TEAM_SERVICE_REQUEST_CONFLICT','replay cannot replace another payload');
select extensions.throws_ok($test$select public.delete_professional_safely(business_id,clinical_professional) from team_editor_fixture$test$,'P0001','TEAM_PROFESSIONAL_HAS_HISTORY','clinical authorship blocks deletion');
select extensions.throws_ok($test$select public.delete_professional_safely(business_id,follow_up_professional) from team_editor_fixture$test$,'P0001','TEAM_PROFESSIONAL_HAS_HISTORY','follow-up history blocks deletion');
select extensions.is((select clinical_entry_count from team_editor_fixture f cross join lateral public.get_professional_dependency_counts(f.business_id,f.clinical_professional)),1::bigint,'counts include clinical authorship');
select extensions.is((select follow_up_count from team_editor_fixture f cross join lateral public.get_professional_dependency_counts(f.business_id,f.follow_up_professional)),1::bigint,'counts include follow-ups');
reset role;
create function private.cita_team_assignment_failure() returns trigger language plpgsql set search_path=pg_catalog,pg_temp as $$
begin if new.service_id=(select failed_service from team_editor_fixture) then raise exception 'TEAM_SYNTHETIC_ASSIGNMENT_FAILURE'; end if; return new; end $$;
create trigger cita_team_assignment_failure before insert on public.professional_services for each row execute function private.cita_team_assignment_failure();
set local role authenticated;
select extensions.throws_ok($test$select public.create_professional_service_safely(business_id,empty_professional,failed_service,'Synthetic failed assignment',30,null) from team_editor_fixture$test$,'P0001','TEAM_SYNTHETIC_ASSIGNMENT_FAILURE','forced assignment failure rolls back the command');
select extensions.is((select count(*) from public.services where id=(select failed_service from team_editor_fixture)),0::bigint,'failed assignment rolls back its service');
reset role;
drop trigger cita_team_assignment_failure on public.professional_services;
drop function private.cita_team_assignment_failure();
create function private.cita_team_deletion_failure() returns trigger language plpgsql set search_path=pg_catalog,pg_temp as $$
begin if old.id=(select empty_professional from team_editor_fixture) then raise exception 'TEAM_SYNTHETIC_DELETE_FAILURE'; end if; return old; end $$;
create trigger cita_team_deletion_failure before delete on public.professionals for each row execute function private.cita_team_deletion_failure();
set local role authenticated;
select extensions.throws_ok($test$select public.delete_professional_safely(business_id,empty_professional) from team_editor_fixture$test$,'P0001','TEAM_SYNTHETIC_DELETE_FAILURE','forced final delete failure rolls back earlier cleanup');
select extensions.is((select changed_by_professional_id from public.patient_profile_change_events where id=(select event_id from team_editor_fixture)),(select empty_professional from team_editor_fixture),'failed delete preserves event attribution');
select extensions.is((select count(*) from public.professional_services where professional_id=(select empty_professional from team_editor_fixture)),1::bigint,'failed delete preserves current assignments');
reset role;
drop trigger cita_team_deletion_failure on public.professionals;
drop function private.cita_team_deletion_failure();
set local role authenticated;
select extensions.throws_ok($test$select public.delete_professional_safely(business_id,foreign_professional) from team_editor_fixture$test$,'P0001','TEAM_PROFESSIONAL_NOT_FOUND','foreign professional cannot be deleted');
select extensions.lives_ok($test$select public.delete_professional_safely(business_id,empty_professional) from team_editor_fixture$test$,'empty professional can be deleted');
select extensions.is((select count(*) from public.professionals where id=(select empty_professional from team_editor_fixture)),0::bigint,'professional is actually removed');
select extensions.is((select count(*) from public.professional_services where professional_id=(select empty_professional from team_editor_fixture)),0::bigint,'configuration assignment is removed by FK');
select extensions.is((select count(*) from public.services where id=(select service_id from team_editor_fixture)),1::bigint,'shared service is preserved');
select extensions.is((select changed_by_professional_id from public.patient_profile_change_events where id=(select event_id from team_editor_fixture)),null::uuid,'audit event remains with historical name and no invalid reference');
reset role;
update public.business_users set status='disabled',disabled_at=now() where business_id=(select business_id from team_editor_fixture) and user_id=(select owner_id from team_editor_fixture);
set local role authenticated;
select extensions.throws_ok($test$select public.delete_professional_safely(business_id,clinical_professional) from team_editor_fixture$test$,'P0001','TEAM_ACCESS_DENIED','revoked owner cannot call the command');
reset role;
select * from extensions.finish();
rollback;
